import fs from 'node:fs';

const path = 'server.ts';
let s = fs.readFileSync(path, 'utf8');

if (!s.includes("import { Pool } from 'pg';")) {
  s = s.replace("import nodemailer from 'nodemailer';", "import nodemailer from 'nodemailer';\nimport { Pool } from 'pg';");
}

const marker = "dotenv.config();\n";
const dbBlock = `\n// Railway PostgreSQL persistence for production admin/funding records.\nconst pgPool = process.env.DATABASE_URL ? new Pool({ connectionString: process.env.DATABASE_URL, ssl: process.env.NODE_ENV === 'production' ? { rejectUnauthorized: false } : undefined }) : null;\nlet pgReady = false;\nasync function ensureProductionDb() {\n  if (!pgPool || pgReady) return Boolean(pgPool);\n  await pgPool.query(\`\n    CREATE TABLE IF NOT EXISTS axi_funding (\n      id TEXT PRIMARY KEY,\n      user_email TEXT NOT NULL,\n      amount NUMERIC(24,8) NOT NULL,\n      method TEXT NOT NULL,\n      status TEXT NOT NULL,\n      stripe_ref TEXT,\n      received_at TIMESTAMPTZ NOT NULL,\n      credited_by_admin BOOLEAN NOT NULL DEFAULT FALSE,\n      credited_at TIMESTAMPTZ,\n      credited_balance NUMERIC(24,8),\n      credited_user_id TEXT,\n      rejected_at TIMESTAMPTZ,\n      rejected_by_admin BOOLEAN NOT NULL DEFAULT FALSE,\n      payload JSONB NOT NULL DEFAULT '{}'::jsonb\n    );\n    CREATE TABLE IF NOT EXISTS axi_payment_methods (\n      id INTEGER PRIMARY KEY DEFAULT 1,\n      config JSONB NOT NULL DEFAULT '{}'::jsonb,\n      updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n    );\n    CREATE TABLE IF NOT EXISTS axi_admin_activity (\n      id BIGSERIAL PRIMARY KEY,\n      action TEXT NOT NULL,\n      target_id TEXT,\n      actor TEXT,\n      details JSONB NOT NULL DEFAULT '{}'::jsonb,\n      created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n    );\n  \`);\n  pgReady = true;\n  return true;\n}\nasync function dbActivity(action, targetId, actor, details = {}) {\n  try { if (await ensureProductionDb()) await pgPool.query('INSERT INTO axi_admin_activity(action,target_id,actor,details) VALUES($1,$2,$3,$4)', [action, targetId || null, actor || 'admin', JSON.stringify(details)]); } catch (e) { console.error('Postgres activity log failed:', e); }\n}\nasync function dbUpsertFunding(entry) {\n  if (!(await ensureProductionDb())) return;\n  await pgPool.query(\`INSERT INTO axi_funding(id,user_email,amount,method,status,stripe_ref,received_at,credited_by_admin,payload) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) ON CONFLICT(id) DO NOTHING\`, [entry.id, entry.userEmail, entry.amount, entry.method, entry.status, entry.stripeRef || null, entry.receivedAt, Boolean(entry.creditedByAdmin), JSON.stringify(entry)]);\n}\nasync function dbFundingList(includeCompleted = false) {\n  if (!(await ensureProductionDb())) return null;\n  const q = includeCompleted ? 'SELECT * FROM axi_funding ORDER BY received_at DESC' : \"SELECT * FROM axi_funding WHERE credited_by_admin = FALSE AND status <> 'Rejected' ORDER BY received_at DESC\";\n  const r = await pgPool.query(q);\n  return r.rows;\n}\nasync function dbUpdateFunding(id, patch) {\n  if (!(await ensureProductionDb())) return false;\n  await pgPool.query(\`UPDATE axi_funding SET status=COALESCE($2,status),credited_by_admin=COALESCE($3,credited_by_admin),credited_at=COALESCE($4,credited_at),credited_balance=COALESCE($5,credited_balance),credited_user_id=COALESCE($6,credited_user_id),rejected_at=COALESCE($7,rejected_at),rejected_by_admin=COALESCE($8,rejected_by_admin),payload=payload || $9::jsonb WHERE id=$1\`, [id, patch.status ?? null, patch.creditedByAdmin ?? null, patch.creditedAt ?? null, patch.creditedBalance ?? null, patch.creditedUserId ?? null, patch.rejectedAt ?? null, patch.rejectedByAdmin ?? null, JSON.stringify(patch)]);\n  return true;\n}\n`;
if (!s.includes('const pgPool =')) {
  if (!s.includes(marker)) throw new Error('dotenv marker not found');
  s = s.replace(marker, marker + dbBlock);
}

// Make Stripe webhook persistence dual-write to PostgreSQL without changing its existing safe file fallback.
const oldWrite = "writeDataFile('pendingDeposits.json', pendingDeposits);\n    }\n    notifyTelegram";
const newWrite = "writeDataFile('pendingDeposits.json', pendingDeposits);\n      dbUpsertFunding(entry).catch(e => console.error('Postgres funding persistence failed:', e));\n    }\n    notifyTelegram";
if (s.includes(oldWrite) && !s.includes('dbUpsertFunding(entry).catch')) s = s.replace(oldWrite, newWrite);

const pendingStart = "app.get('/api/admin/funding/pending', (_req, res) => {";
const pendingEnd = "app.post('/api/admin/funding/:id/reject',";
const a = s.indexOf(pendingStart);
const b = s.indexOf(pendingEnd);
if (a < 0 || b < 0 || b <= a) throw new Error('Funding route markers not found');
const fundingRoutes = `app.get('/api/admin/funding/pending', async (_req, res) => {\n  try {\n    const dbRows = await dbFundingList(false);\n    if (dbRows) return res.json({ deposits: dbRows.map(r => ({ id:r.id, userEmail:r.user_email, amount:Number(r.amount), method:r.method, status:r.status, stripeRef:r.stripe_ref, receivedAt:r.received_at, creditedByAdmin:r.credited_by_admin, creditedAt:r.credited_at, creditedBalance:r.credited_balance, creditedUserId:r.credited_user_id })) });\n    const deposits = readDataFile<any[]>('pendingDeposits.json', []);\n    res.json({ deposits: deposits.filter(d => !d.creditedByAdmin && d.status !== 'Rejected') });\n  } catch (e) { console.error('Funding queue failed:', e); res.status(500).json({ error:'Unable to load funding queue' }); }\n});\n\napp.post('/api/admin/funding/:id/credit', async (req, res) => {\n  const id = String(req.params.id || '');\n  const deposits = readDataFile<any[]>('pendingDeposits.json', []);\n  const index = deposits.findIndex(d => d.id === id);\n  if (index < 0) return res.status(404).json({ error: 'Funding record not found' });\n  const deposit = deposits[index];\n  if (deposit.creditedByAdmin || deposit.status === 'Credited') return res.status(409).json({ error: 'Funding record has already been credited' });\n  const creditedBalance = Number(req.body?.creditedBalance);\n  const userId = String(req.body?.userId || '');\n  if (!Number.isFinite(creditedBalance) || creditedBalance <= 0) return res.status(400).json({ error: 'Invalid credited balance' });\n  deposits[index] = { ...deposit, status: 'Credited', creditedByAdmin: true, creditedAt: new Date().toISOString(), creditedBalance, creditedUserId: userId };\n  writeDataFile('pendingDeposits.json', deposits);\n  await dbUpdateFunding(id, deposits[index]);\n  await dbActivity('funding.manual_credit', id, 'admin', { userEmail: deposit.userEmail, amount: creditedBalance, userId });\n  res.json({ success: true, deposit: deposits[index] });\n});\n\n`;
s = s.slice(0, a) + fundingRoutes + s.slice(b);

const rejectStart = "app.post('/api/admin/funding/:id/reject',";
const payStart = "const PAYMENT_METHODS_FILE = 'paymentMethods.json';";
const c = s.indexOf(rejectStart);
const d = s.indexOf(payStart);
if (c < 0 || d < 0 || d <= c) throw new Error('Reject/payment markers not found');
const rejectRoute = `app.post('/api/admin/funding/:id/reject', async (req, res) => {\n  const id = String(req.params.id || '');\n  const deposits = readDataFile<any[]>('pendingDeposits.json', []);\n  const index = deposits.findIndex(d => d.id === id);\n  if (index < 0) return res.status(404).json({ error: 'Funding record not found' });\n  if (deposits[index].creditedByAdmin) return res.status(409).json({ error: 'Credited funding cannot be rejected' });\n  deposits[index] = { ...deposits[index], status: 'Rejected', rejectedAt: new Date().toISOString(), rejectedByAdmin: true };\n  writeDataFile('pendingDeposits.json', deposits);\n  await dbUpdateFunding(id, deposits[index]);\n  await dbActivity('funding.reject', id, 'admin', { userEmail: deposits[index].userEmail, reason: req.body?.reason || '' });\n  res.json({ success: true, deposit: deposits[index] });\n});\n\n`;
s = s.slice(0, c) + rejectRoute + s.slice(d);

// Replace payment-method routes with DB-first persistence while retaining file fallback.
const pmStart = s.indexOf("app.get('/api/admin/payment-methods'");
const portMarker = s.indexOf("const PORT = Number(process.env.PORT) || 3000;");
if (pmStart < 0 || portMarker < 0 || portMarker <= pmStart) throw new Error('Payment-method markers not found');
const pmRoutes = `app.get('/api/admin/payment-methods', async (_req, res) => {\n  const fallback = { bankTransfer: { enabled: false, bankName: '', accountName: '', accountNumber: '', routingNumber: '', swiftBic: '', currency: '', instructions: '' }, instantTransfer: { enabled: false, providerName: '', accountName: '', accountNumber: '', instructions: '' }, crypto: { enabled: false, asset: '', network: '', address: '', memo: '', instructions: '' } };\n  try {\n    if (await ensureProductionDb()) { const r = await pgPool.query('SELECT config FROM axi_payment_methods WHERE id=1'); return res.json({ success:true, methods:r.rows[0]?.config || fallback }); }\n    res.json({ success:true, methods:readDataFile<any>(PAYMENT_METHODS_FILE, fallback) });\n  } catch (e) { console.error('Payment methods load failed:', e); res.status(500).json({ error:'Unable to load payment methods' }); }\n});\n\napp.post('/api/admin/payment-methods', async (req, res) => {\n  const incoming = req.body || {};\n  const methods = {\n    bankTransfer: { enabled:Boolean(incoming.bankTransfer?.enabled), bankName:String(incoming.bankTransfer?.bankName||'').trim(), accountName:String(incoming.bankTransfer?.accountName||'').trim(), accountNumber:String(incoming.bankTransfer?.accountNumber||'').trim(), routingNumber:String(incoming.bankTransfer?.routingNumber||'').trim(), swiftBic:String(incoming.bankTransfer?.swiftBic||'').trim(), currency:String(incoming.bankTransfer?.currency||'').trim(), instructions:String(incoming.bankTransfer?.instructions||'').trim() },\n    instantTransfer: { enabled:Boolean(incoming.instantTransfer?.enabled), providerName:String(incoming.instantTransfer?.providerName||'').trim(), accountName:String(incoming.instantTransfer?.accountName||'').trim(), accountNumber:String(incoming.instantTransfer?.accountNumber||'').trim(), instructions:String(incoming.instantTransfer?.instructions||'').trim() },\n    crypto: { enabled:Boolean(incoming.crypto?.enabled), asset:String(incoming.crypto?.asset||'').trim(), network:String(incoming.crypto?.network||'').trim(), address:String(incoming.crypto?.address||'').trim(), memo:String(incoming.crypto?.memo||'').trim(), instructions:String(incoming.crypto?.instructions||'').trim() }\n  };\n  try {\n    if (await ensureProductionDb()) await pgPool.query('INSERT INTO axi_payment_methods(id,config) VALUES(1,$1) ON CONFLICT(id) DO UPDATE SET config=EXCLUDED.config,updated_at=NOW()', [JSON.stringify(methods)]);\n    writeDataFile(PAYMENT_METHODS_FILE, methods);\n    await dbActivity('payment_methods.updated', 'payment-methods', 'admin', methods);\n    res.json({ success:true, methods });\n  } catch (e) { console.error('Payment methods save failed:', e); res.status(500).json({ error:'Unable to save payment methods' }); }\n});\n\napp.get('/api/admin/activity', async (_req, res) => {\n  try { if (!(await ensureProductionDb())) return res.json({ activities:[] }); const r=await pgPool.query('SELECT id,action,target_id,actor,details,created_at FROM axi_admin_activity ORDER BY created_at DESC LIMIT 200'); res.json({ activities:r.rows }); } catch (e) { console.error('Activity load failed:', e); res.status(500).json({ error:'Unable to load activity' }); }\n});\n\n`;
s = s.slice(0, pmStart) + pmRoutes + s.slice(portMarker);

fs.writeFileSync(path, s);
console.log('PostgreSQL funding/payment persistence applied successfully.');
